import os
from bioblend.galaxy import GalaxyInstance

API_KEY = open('/run/secrets/galaxy_api_key').read().strip()
gi = GalaxyInstance(url='https://usegalaxy.org', key=API_KEY)

hist_id = 'bbd44e69cb8906b540a6705f6c6ceccd'
tool_id = 'toolshed.g2.bx.psu.edu/repos/goeckslab/phykit_metrics/phykit_metrics/0.2.0+galaxy0'

inputs = {
    "operation": {
        "selector": "total_tree_length",
        "input_mode": {
            "selector": "grouped_zip_archives",
            "archives": [
                {
                    "label": "animals",
                    "archive": {"src": "hda", "id": "f9cad7b01a4721352b8bbef929c7bc8c"}
                },
                {
                    "label": "fungi",
                    "archive": {"src": "hda", "id": "f9cad7b01a4721359198e53908f87082"}
                }
            ],
            "filter_suffix": ".treefile"
        }
    }
}

try:
    result = gi.tools.run_tool(hist_id, tool_id, inputs)
    print(f"Job submitted successfully!")
    print(f"Job ID: {result}")
except Exception as e:
    print(f"Error: {e}")
PYEOF

